export interface ConnectorConfig {
  /** Mailchimp API key (from MAILCHIMP_API_KEY env var) */
  mailchimpApiKey: string
  /** Mailchimp audience/list ID (from MAILCHIMP_LIST_ID env var) */
  mailchimpListId: string
  /** Mailchimp server prefix, e.g. "us1" (from MAILCHIMP_SERVER_PREFIX env var, default "us1") */
  mailchimpServerPrefix?: string
  /** Injected fetch for testing */
  fetch?: typeof fetch
}

export interface StripeCheckoutSessionCompleted {
  id: string
  customer: string
  customer_email: string
  metadata: {
    plan: string
    [key: string]: unknown
  }
  payment_status: string
  mode: string
  status: string
  [key: string]: unknown
}

export interface HandleResult {
  mailchimpMemberId: string
  email: string
  tags: string[]
}

function base64Encode(str: string): string {
  if (typeof btoa === 'function') return btoa(str)
  return Buffer.from(str).toString('base64')
}

export async function handle(
  payload: StripeCheckoutSessionCompleted,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  // Validate required fields
  if (!payload.customer_email) {
    throw new Error('Missing required field: customer_email')
  }
  if (!payload.metadata?.plan) {
    throw new Error('Missing required field: metadata.plan')
  }

  const email = payload.customer_email
  const plan = payload.metadata.plan
  const serverPrefix = config.mailchimpServerPrefix ?? 'us1'
  const url = `https://${serverPrefix}.api.mailchimp.com/3.0/lists/${config.mailchimpListId}/members`

  const authString = `apikey:${config.mailchimpApiKey}`
  const authHeader = `Basic ${base64Encode(authString)}`

  const body = {
    email_address: email,
    status_if_new: 'subscribed',
    tags: [plan],
  }

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      Authorization: authHeader,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    throw new Error(`Mailchimp API error: ${response.status} ${response.statusText} for POST ${url}`)
  }

  const result = (await response.json()) as {
    id: string
    email_address: string
    tags: Array<{ name: string; status: string }>
  }

  return {
    mailchimpMemberId: result.id,
    email: result.email_address,
    tags: result.tags.map((t) => t.name),
  }
}

