describe('handle', () => {
  it('maps fields correctly and calls Mailchimp with expected body', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url.includes('/lists/test-list-id/members') ? jsonResponse({ id: 'member123', email_address: 'test@example.com', tags: [{ name: 'pro', status: 'active' }] }, 201) : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: StripeCheckoutSessionCompleted = {
      id: 'cs_test_123',
      customer: 'cus_456',
      customer_email: 'test@example.com',
      metadata: { plan: 'pro' },
      payment_status: 'paid',
      mode: 'subscription',
      status: 'complete',
    }

    const config: ConnectorConfig = {
      mailchimpApiKey: 'test-key',
      mailchimpListId: 'test-list-id',
      mailchimpServerPrefix: 'us2',
      fetch,
    }

    const result = await handle(payload, config)

    expect(calls.length).toBe(1)
    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toBe('https://us2.api.mailchimp.com/3.0/lists/test-list-id/members')
    expect(call.headers.get('authorization')).toBe('Basic YXBpa2V5OnRlc3Qta2V5')
    expect(call.json).toEqual({
      email_address: 'test@example.com',
      status_if_new: 'subscribed',
      tags: ['pro'],
    })
    expect(result.mailchimpMemberId).toBe('member123')
    expect(result.email).toBe('test@example.com')
    expect(result.tags).toEqual(['pro'])
  })

  it('uses default server prefix when not provided', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url.includes('/lists/list-abc/members') ? jsonResponse({ id: 'mem1', email_address: 'a@b.com', tags: [] }, 200) : jsonResponse({}, 404)
    )

    const payload: StripeCheckoutSessionCompleted = {
      id: 'cs_1',
      customer: 'cus_1',
      customer_email: 'a@b.com',
      metadata: { plan: 'basic' },
      payment_status: 'paid',
      mode: 'subscription',
      status: 'complete',
    }

    const config: ConnectorConfig = {
      mailchimpApiKey: 'key',
      mailchimpListId: 'list-abc',
      fetch,
    }

    await handle(payload, config)

    expect(calls[0].url).toBe('https://us1.api.mailchimp.com/3.0/lists/list-abc/members')
  })

  it('throws when customer_email is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = {
      id: 'cs_1',
      customer: 'cus_1',
      metadata: { plan: 'basic' },
      payment_status: 'paid',
      mode: 'subscription',
      status: 'complete',
    } as unknown as StripeCheckoutSessionCompleted

    const config: ConnectorConfig = {
      mailchimpApiKey: 'key',
      mailchimpListId: 'list-1',
      fetch,
    }

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: customer_email')
  })

  it('throws when metadata.plan is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = {
      id: 'cs_1',
      customer: 'cus_1',
      customer_email: 'test@test.com',
      metadata: {},
      payment_status: 'paid',
      mode: 'subscription',
      status: 'complete',
    } as unknown as StripeCheckoutSessionCompleted

    const config: ConnectorConfig = {
      mailchimpApiKey: 'key',
      mailchimpListId: 'list-1',
      fetch,
    }

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: metadata.plan')
  })

  it('throws on non-2xx response from Mailchimp', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ detail: 'Invalid API key' }, 401))

    const payload: StripeCheckoutSessionCompleted = {
      id: 'cs_1',
      customer: 'cus_1',
      customer_email: 'test@test.com',
      metadata: { plan: 'pro' },
      payment_status: 'paid',
      mode: 'subscription',
      status: 'complete',
    }

    const config: ConnectorConfig = {
      mailchimpApiKey: 'bad-key',
      mailchimpListId: 'list-1',
      fetch,
    }

    await expect(handle(payload, config)).rejects.toThrow('Mailchimp API error: 401 Unauthorized for POST')
    expect(calls.length).toBe(1)
  })

  it('includes plan as tag in request', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url.includes('/members') ? jsonResponse({ id: 'm1', email_address: 'x@y.com', tags: [{ name: 'enterprise', status: 'active' }] }, 200) : jsonResponse({}, 404)
    )

    const payload: StripeCheckoutSessionCompleted = {
      id: 'cs_1',
      customer: 'cus_1',
      customer_email: 'x@y.com',
      metadata: { plan: 'enterprise' },
      payment_status: 'paid',
      mode: 'subscription',
      status: 'complete',
    }

    const config: ConnectorConfig = {
      mailchimpApiKey: 'key',
      mailchimpListId: 'list-1',
      fetch,
    }

    await handle(payload, config)
    expect(calls[0].json).toEqual({
      email_address: 'x@y.com',
      status_if_new: 'subscribed',
      tags: ['enterprise'],
    })
  })
})

